import json, re
from docx import Document

# Load data
with open('employee_data.json') as f:
    data = json.load(f)

relocation_yes = str(data.get('RELOCATION_PACKAGE', '')).strip().lower() == 'yes'

def set_paragraph_text(paragraph, text):
    runs = paragraph.runs
    if runs:
        runs[0].text = text
        for r in runs[1:]:
            r.text = ''
    else:
        paragraph.add_run(text)

def handle_conditionals(paragraphs):
    to_delete = []
    in_block = False
    for p in list(paragraphs):
        text = p.text
        if '{{IF_RELOCATION}}' in text:
            if relocation_yes:
                text = text.replace('{{IF_RELOCATION}}', '')
                if '{{END_IF_RELOCATION}}' in text:
                    text = text.replace('{{END_IF_RELOCATION}}', '')
                    set_paragraph_text(p, text)
                    in_block = False
                else:
                    set_paragraph_text(p, text)
                    in_block = True
            else:
                # remove from IF to END
                if '{{END_IF_RELOCATION}}' in text:
                    before, _, rest = text.partition('{{IF_RELOCATION}}')
                    _, _, after = rest.partition('{{END_IF_RELOCATION}}')
                    new_text = before + after
                    if new_text.strip() == '':
                        to_delete.append(p)
                    else:
                        set_paragraph_text(p, new_text)
                    in_block = False
                else:
                    to_delete.append(p)
                    in_block = True
        elif '{{END_IF_RELOCATION}}' in text:
            if relocation_yes:
                text = text.replace('{{END_IF_RELOCATION}}', '')
                set_paragraph_text(p, text)
            else:
                to_delete.append(p)
            in_block = False
        else:
            if in_block and not relocation_yes:
                to_delete.append(p)
    for p in to_delete:
        p._element.getparent().remove(p._element)

pattern = re.compile(r'\{\{([A-Z0-9_]+)\}\}')

def replace_in_paragraph(para):
    text = para.text
    matches = pattern.findall(text)
    if not matches:
        return
    new_text = text
    for key in matches:
        placeholder = '{{' + key + '}}'
        if key in data:
            new_text = new_text.replace(placeholder, str(data[key]))
    if new_text != text:
        set_paragraph_text(para, new_text)


def process_container(container):
    # conditionals first
    handle_conditionals(container.paragraphs)
    # replace placeholders
    for para in container.paragraphs:
        replace_in_paragraph(para)
    # tables (including nested)
    for table in container.tables:
        for row in table.rows:
            for cell in row.cells:
                process_container(cell)

# Load document and process
 doc = Document('offer_letter_template.docx')

process_container(doc)

for section in doc.sections:
    process_container(section.header)
    process_container(section.footer)

# Save output
output_path = '/root/offer_letter_filled.docx'
doc.save(output_path)
print('Saved', output_path)
